cat > src/CheckoutPricing.Domain/DiscountPolicy.cs <<'EOF'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int For(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.For(subtotalCents, tier);
        var promoCents = PromoCents(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }

    private static int PromoCents(string? promoCode, int remainingCents)
    {
        if (string.Equals(promoCode, "WELCOME5", StringComparison.OrdinalIgnoreCase))
            return WelcomeFiveCents;
        if (string.Equals(promoCode, "SUMMER10", StringComparison.OrdinalIgnoreCase))
            return Math.Min(remainingCents / 10, SummerTenCapCents);
        return 0;
    }
}
EOF
